import sys,types,unittest,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
sys.path[:0]=[str(ROOT/'alternatives/advisor-first/tests'),str(ROOT/'alternatives/advisor-first')]
import server
before=Path(__file__).with_name('before')/'alternatives/advisor-first'
for name in ['natural_state','composition_recovery','advisor_memory','natural_agent','natural_flow']:
 m=types.ModuleType(name);m.__file__=str(ROOT/'alternatives/advisor-first'/f'{name}.py');sys.modules[name]=m
 exec(compile((before/f'{name}.py').read_text(),m.__file__,'exec'),m.__dict__)
server.NaturalConversation=sys.modules['natural_flow'].NaturalConversation
server.NaturalAgent=sys.modules['natural_agent'].NaturalAgent
names=['test_ai_send.AISendTests.test_send_is_one_deliberate_request_without_a_confirmation_modal', 'test_curriculum_flow.CurriculumFlowTests.test_explicit_request_to_explain_again_authorizes_recap_and_visual', 'test_curriculum_flow.CurriculumFlowTests.test_failed_composition_can_deliver_the_requested_reviewed_lesson', 'test_curriculum_flow.CurriculumFlowTests.test_new_layer_can_reuse_evidence_without_repeating_the_paths', 'test_curriculum_flow.CurriculumFlowTests.test_reported_two_turn_sequence_reuses_citation_without_repeating_visual_or_receipt', 'test_natural_flow.NaturalFlowTests.test_pending_ambiguity_does_not_leak_to_another_visit_with_matching_versions', 'test_task_work_flow.TaskWorkFlowTests.test_same_request_replay_preserves_current_work_and_historical_replay_suppresses_it', 'test_timing_recovery.TimingRecoveryTests.test_failed_turns_never_trigger_a_case_specific_question_or_lesson', 'test_understanding_flow.UnderstandingFlowTests.test_parts_backed_original_visual_is_limited_through_the_real_controller', 'test_utility_button_gates.UtilityButtonGatesTests.test_concept_link_preserves_current_practical_question_without_model_call', 'test_education_lifecycle.EducationLifecycleTests', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_controlled_unexpected_failure_is_value_free_and_exact_replay_recovers_capture', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_current_lowercase_mixed_provider_proposals_are_json_safe', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_known_composition_unavailability_keeps_provider_without_new_intake', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_original_fictional_model_shape_t06_only_is_json_safe', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_pcp_capture_after_cobra_timing_and_naples_returns_complete_json', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_reversed_provider_proposals_preserve_one_item', 'test_provider_incident_recovery.ProviderIncidentRecoveryTests.test_sensitive_provider_save_omission_and_explicit_roundtrip_are_separate', 'test_understanding_flow.UnderstandingFlowTests.test_cost_question_uses_shared_blocks_and_one_existing_composition_stage', 'test_understanding_flow.UnderstandingFlowTests.test_free_lesson_and_its_replay_recheck_source_authority_without_generation', 'test_understanding_flow.UnderstandingFlowTests.test_timing_question_preserves_reported_month_without_a_personal_window']
result=unittest.TextTestRunner(verbosity=1).run(unittest.defaultTestLoader.loadTestsFromNames(names))
Path(__file__).with_name('baseline-result.json').write_text(json.dumps({'run':result.testsRun,'failures':[t.id() for t,_ in result.failures],'errors':[t.id() for t,_ in result.errors]},indent=2)+'\n')
